import React, { useState } from 'react';
import { User, Briefcase, Upload, CheckCircle, X, FileText, Award, ShieldCheck } from 'lucide-react';

const Register = () => {
  const [showModal, setShowModal] = useState(null);
  const [isVerifying, setIsVerifying] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
    setIsVerifying(true);
    // Simulate a verification delay
    setTimeout(() => {
      alert("Information sent for verification. You will be notified soon!");
      setShowModal(null);
      setIsVerifying(false);
    }, 2000);
  };

  return (
    <div className="min-h-screen bg-[#f3f4f9] flex flex-col items-center justify-center p-6 font-sans">
      <div className="text-center mb-10">
        <h1 className="text-4xl font-extrabold text-gray-900 mb-2">Create Your Account</h1>
        <p className="text-gray-500">Join the most trusted Talent Pool Management System</p>
      </div>
      
      {/* The Central Oval Toggle */}
      <div className="bg-white p-2 rounded-full shadow-2xl flex border border-gray-100 w-full max-w-lg">
        <button 
          onClick={() => setShowModal('student')}
          className="flex-1 flex flex-col items-center justify-center py-6 rounded-full hover:bg-purple-50 transition-all group"
        >
          <div className="bg-purple-100 text-purple-600 p-3 rounded-full mb-2 group-hover:bg-purple-600 group-hover:text-white transition-all">
            <User size={28} />
          </div>
          <span className="font-bold text-gray-800">Student</span>
        </button>

        <div className="w-[1px] bg-gray-200 my-4"></div>

        <button 
          onClick={() => setShowModal('hr')}
          className="flex-1 flex flex-col items-center justify-center py-6 rounded-full hover:bg-blue-50 transition-all group"
        >
          <div className="bg-blue-100 text-blue-600 p-3 rounded-full mb-2 group-hover:bg-blue-600 group-hover:text-white transition-all">
            <Briefcase size={28} />
          </div>
          <span className="font-bold text-gray-800">HR / Company</span>
        </button>
      </div>

      {/* Registration Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-md flex items-center justify-center z-50 p-4">
          <div className="bg-white w-full max-w-2xl rounded-[2rem] shadow-2xl overflow-hidden animate-in zoom-in duration-200">
            
            {/* Header */}
            <div className={`p-6 text-white flex justify-between items-center ${showModal === 'student' ? 'bg-[#7c5dfa]' : 'bg-[#2563eb]'}`}>
              <div className="flex items-center gap-2">
                <ShieldCheck size={24} />
                <h2 className="text-xl font-bold uppercase tracking-tight">
                  {showModal === 'student' ? 'Student Verification' : 'Company Verification'}
                </h2>
              </div>
              <button onClick={() => setShowModal(null)} className="hover:rotate-90 transition-transform">
                <X size={24} />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="p-8 grid grid-cols-1 md:grid-cols-2 gap-4 max-h-[80vh] overflow-y-auto">
              
              {showModal === 'student' ? (
                <>
                  {/* STUDENT FIELDS */}
                  <div className="col-span-2 text-sm font-bold text-gray-400 uppercase">Basic Info</div>
                  <input type="text" placeholder="Full Name" className="input-style" required />
                  <input type="text" placeholder="College Name" className="input-style" required />
                  
                  <div className="col-span-2 text-sm font-bold text-gray-400 uppercase mt-2">Professional Info</div>
                  <input type="text" placeholder="Key Skills (e.g. Java, React)" className="input-style" required />
                  <select className="input-style" required>
                    <option value="">Experience Level</option>
                    <option value="fresher">Fresher</option>
                    <option value="intern">Internship (6mo+)</option>
                    <option value="junior">Junior (1yr+)</option>
                  </select>
                  
                  <div className="col-span-2 border-2 border-dashed border-purple-100 p-6 rounded-2xl text-center bg-purple-50/30">
                    <FileText className="mx-auto text-purple-400 mb-2" />
                    <p className="text-sm font-medium text-gray-600">Upload Resume & Certificates</p>
                    <input type="file" className="mt-4 text-xs block w-full text-gray-400 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:bg-purple-100 file:text-purple-700 hover:file:bg-purple-200" required multiple />
                  </div>
                </>
              ) : (
                <>
                  {/* HR FIELDS */}
                  <div className="col-span-2 text-sm font-bold text-gray-400 uppercase">Company Info</div>
                  <input type="text" placeholder="Company Name" className="input-style" required />
                  <input type="text" placeholder="Company Website" className="input-style" required />
                  <input type="text" placeholder="Company Registration ID" className="input-style" required />
                  <input type="text" placeholder="Official HR Email" className="input-style" required />
                  
                  <div className="col-span-2 text-sm font-bold text-gray-400 uppercase mt-2">Hiring Needs</div>
                  <input type="text" placeholder="Job Roles (e.g. SDE-1)" className="input-style" required />
                  <input type="text" placeholder="Required Skills" className="input-style" required />

                  <div className="col-span-2 border-2 border-dashed border-blue-100 p-6 rounded-2xl text-center bg-blue-50/30">
                    <Award className="mx-auto text-blue-400 mb-2" />
                    <p className="text-sm font-medium text-gray-600">Upload HR Identity / Business License</p>
                    <input type="file" className="mt-4 text-xs block w-full text-gray-400 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:bg-blue-100 file:text-blue-700 hover:file:bg-blue-200" required />
                  </div>
                </>
              )}

              {/* Action Button */}
              <button 
                type="submit"
                disabled={isVerifying}
                className={`col-span-2 py-4 rounded-xl font-bold text-white shadow-lg transition-all transform active:scale-95 flex items-center justify-center gap-2 ${
                  isVerifying ? 'bg-orange-400 animate-pulse' : (showModal === 'student' ? 'bg-[#7c5dfa]' : 'bg-[#2563eb]')
                }`}
              >
                {isVerifying ? 'Authenticating Data...' : 'Submit for Verification'}
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Simple style helper for inputs */}
      <style>{`
        .input-style {
          width: 100%;
          padding: 0.75rem 1rem;
          background-color: #f9fafb;
          border: 1px solid #e5e7eb;
          border-radius: 0.75rem;
          outline: none;
          transition: all 0.2s;
        }
        .input-style:focus {
          border-color: #7c5dfa;
          box-shadow: 0 0 0 4px rgba(124, 93, 250, 0.1);
          background-color: white;
        }
      `}</style>
    </div>
  );
};

export default Register;
